<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';require __DIR__.'/app/actions.php';require __DIR__.'/app/views.php';
require __DIR__.'/app/install-errors.php';
if(cfg()['installed']){http_response_code(404);exit('A instalação já foi concluída.');}
$error='';$stage='CONEXAO';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $lock=fopen(__DIR__.'/app/storage/install.lock','c+');
 try{
  if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))throw new RuntimeException('Já existe uma instalação em andamento. Aguarde.');$fresh=require (is_file(__DIR__.'/app/config.php')?__DIR__.'/app/config.php':__DIR__.'/app/config.example.php');if($fresh['installed'])throw new RuntimeException('A instalação já foi concluída.');checkCsrf();$token=(string)($_POST['install_token']??'');if($fresh['install_token']===''||!hash_equals($fresh['install_token'],$token))throw new RuntimeException('Código de instalação inválido. Use o código do LEIA-ME deste pacote.');
  foreach(['pdo_mysql','mbstring','fileinfo','gd','curl'] as $ext)if(!extension_loaded($ext))throw new RuntimeException('Ative a extensão PHP '.$ext.' na hospedagem antes de instalar.');
  $host=textField('db_host',1,190);if(!preg_match('/^[a-zA-Z0-9.-]+$/',$host))throw new RuntimeException('Host do banco inválido.');$name=textField('db_name',1,64);$dbUser=textField('db_user',1,100);$dbPass=(string)($_POST['db_password']??'');if(!preg_match('/^[a-zA-Z0-9_]+$/',$name))throw new RuntimeException('Nome do banco inválido.');
  $adminName=textField('name',2,100);$email=validEmail(textField('email',3,190));$pass=passwordInput();$operator=textField('operator_name',2,150);$mailFrom=validEmail(textField('mail_from',3,190));
  $fresh['db']=['driver'=>'mysql','host'=>$host,'port'=>3306,'name'=>$name,'user'=>$dbUser,'password'=>$dbPass];$GLOBALS['config']=$fresh;
  $pdo=db();$stage='VERIFICACAO';$exists=$pdo->prepare("SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='users'");$exists->execute();if((int)$exists->fetchColumn()>0)throw new RuntimeException('Use um banco novo e exclusivo do Trokar.ia. Já existe uma tabela de usuários nesse banco. Não apague um banco em uso.');
  if(!is_writable(__DIR__.'/app')||!is_writable(__DIR__.'/app/storage/photos'))throw new RuntimeException('O PHP precisa conseguir gravar a configuração e a pasta de fotos.');$stage='TABELAS';schema($pdo);$stage='ADMIN';
  tx(function()use($adminName,$email,$pass){sql("INSERT INTO users(name,email,password_hash,city,state,role,email_verified,created_at) VALUES(?,?,?,'Camboriú','SC','ADMIN',1,?)",[$adminName,$email,password_hash($pass,PASSWORD_DEFAULT),now()]);});
  $fresh['app_key']=bin2hex(random_bytes(32));$fresh['installed']=true;$fresh['install_token']='';$fresh['operator']=['name'=>$operator,'contact'=>$email,'privacy_contact'=>$email];$fresh['mail']['from']=$mailFrom;writeConfig($fresh);flock($lock,LOCK_UN);fclose($lock);flash('Instalação concluída. Entre com seu e-mail e senha e configure o envio de e-mails e a IA no admin.');go('login');
 }catch(Throwable $ex){if(is_resource($lock)){flock($lock,LOCK_UN);fclose($lock);}if($ex instanceof PDOException){$error=installationDatabaseError($ex,$stage);error_log('Trokar instalação: etapa '.$stage.'; código MySQL '.(int)($ex->errorInfo[1]??0).'.');}else $error=$ex->getMessage();$GLOBALS['config']=require (is_file(__DIR__.'/app/config.php')?__DIR__.'/app/config.php':__DIR__.'/app/config.example.php');}
}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Instalar Trokar.ia</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/platform.css"></head><body><main class="container platform-main"><section class="form-panel wide"><img src="assets/logo.svg" width="210" alt="Trokar.ia"><h1>Vamos começar.</h1><p>Use um banco MySQL novo, exclusivo do Trokar.ia. A instalação cria as tabelas e sua conta de administrador, sem anúncios fictícios.</p><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><form method="post" class="modal-form"><?=csrfField()?><?php field('install_token','Código de instalação do LEIA-ME','',type:'password',max:100);?><h2>Banco da Hostinger</h2><?php field('db_host','Host do MySQL','localhost');field('db_name','Nome do banco','',max:64);field('db_user','Usuário do banco','',max:100);field('db_password','Senha do banco','',type:'password',max:300);?><h2>Sua conta de administrador</h2><?php field('name','Seu nome','',max:100);field('email','E-mail do administrador','',type:'email',max:190);field('password','Senha do administrador (12 a 72 caracteres)','',type:'password',max:72);field('operator_name','Nome / razão social do responsável','Trokar.ia',max:150);field('mail_from','E-mail remetente da plataforma','nao-responda@trokar.ia.br',type:'email',max:190);?><button class="button primary" type="submit">Instalar a plataforma</button></form></section></main></body></html>
